fn first_even_odd_indices(lst: Vec<i32>) -> (usize, usize) {
    // Find the index of the first even element
    let first_even = lst
        .iter()
        .position(|&x| x % 2 == 0)
        .expect("The list must contain at least one even number");

    // Find the index of the first odd element
    let first_odd = lst
        .iter()
        .position(|&x| x % 2 != 0)
        .expect("The list must contain at least one odd number");

    (first_even, first_odd)
}

